import React, { useEffect, useState } from "react";

export default function AdminWithdrawRequests({ onCancel }) {
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("authToken");

  useEffect(() => {
    fetchAllRequests();
  }, []);

  const fetchAllRequests = async () => {
    setLoading(true);
    setMessage("");

    try {
      const res = await fetch("http://localhost:8080/api/withdraw/all", {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      if (!res.ok) {
        throw new Error(`Failed to fetch: ${res.status}`);
      }

      const data = await res.json();
      setRequests(data);
    } catch (err) {
      console.error("Error fetching withdraw requests:", err);
      setMessage("ডেটা লোড করতে ব্যর্থ হয়েছে।");
    } finally {
      setLoading(false);
    }
  };

  const handleAction = async (id, action) => {
    setMessage("");

    try {
      const res = await fetch(
        `http://localhost:8080/api/withdraw/${action}/${id}`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }
      );

      if (!res.ok) {
        const errorText = await res.text();
        throw new Error(`Failed: ${res.status} ${errorText}`);
      }

      setMessage(`Request ${action}d successfully.`);
      fetchAllRequests();
    } catch (err) {
      console.error(`Error on ${action}:`, err);
      setMessage(`Failed to ${action} request: ${err.message}`);
    }
  };

  const renderStatusBadge = (status) => {
    const base = "px-2 py-1 rounded text-xs font-semibold text-white";
    const colors = {
      PENDING: "bg-yellow-500",
      APPROVED: "bg-blue-600",
      REJECTED: "bg-red-600",
      COMPLETED: "bg-green-600",
    };
    return <span className={`${base} ${colors[status] || "bg-gray-500"}`}>{status}</span>;
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-6">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800">📤 সকল উইথড্র রিকোয়েস্ট</h2>
        <button
          onClick={onCancel}
          className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-md text-sm font-medium shadow"
        >
          ⬅️ হোমে ফিরে যান
        </button>
      </div>

      {message && (
        <div
          className={`px-4 py-3 mb-6 rounded-md font-medium ${
            message.includes("Failed")
              ? "bg-red-100 text-red-800"
              : "bg-green-100 text-green-800"
          }`}
        >
          {message}
        </div>
      )}

      {loading ? (
        <p className="text-center text-gray-600">লোড হচ্ছে...</p>
      ) : requests.length === 0 ? (
        <p className="text-center text-gray-500">কোনো রিকোয়েস্ট পাওয়া যায়নি।</p>
      ) : (
        <div className="overflow-x-auto bg-white shadow rounded-lg">
          <table className="min-w-full divide-y divide-gray-200 text-sm text-left">
            <thead className="bg-gray-100 text-gray-700 uppercase text-xs font-bold">
              <tr>
                <th className="px-4 py-3">ID</th>
                <th className="px-4 py-3">Email</th>
                <th className="px-4 py-3">Amount</th>
                <th className="px-4 py-3">Method</th>
                <th className="px-4 py-3">Txn ID</th>
                <th className="px-4 py-3">Receiver</th>
                <th className="px-4 py-3">Status</th>
                <th className="px-4 py-3">Date</th>
                <th className="px-4 py-3">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {requests.map((req) => (
                <tr key={req.id} className="hover:bg-gray-50">
                  <td className="px-4 py-2">{req.id}</td>
                  <td className="px-4 py-2 text-indigo-600 font-semibold">
                    {req.user?.email || "N/A"}
                  </td>
                  <td className="px-4 py-2">৳ {Number(req.amount).toFixed(2)}</td>
                  <td className="px-4 py-2">{req.method}</td>
                  <td className="px-4 py-2">{req.transactionId}</td>
                  <td className="px-4 py-2">{req.receiverNumber}</td>
                  <td className="px-4 py-2">{renderStatusBadge(req.status)}</td>
                  <td className="px-4 py-2">{new Date(req.requestedAt).toLocaleString()}</td>
                  <td className="px-4 py-2 space-x-1">
                    {req.status === "PENDING" && (
                      <>
                        <button
                          onClick={() => handleAction(req.id, "approve")}
                          className="bg-green-600 hover:bg-green-700 text-white px-3 py-1 rounded text-xs font-semibold"
                        >
                          Approve
                        </button>
                        <button
                          onClick={() => handleAction(req.id, "reject")}
                          className="bg-red-600 hover:bg-red-700 text-white px-3 py-1 rounded text-xs font-semibold"
                        >
                          Reject
                        </button>
                      </>
                    )}
                    {req.status === "APPROVED" && (
                      <button
                        onClick={() => handleAction(req.id, "complete")}
                        className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1 rounded text-xs font-semibold"
                      >
                        Complete
                      </button>
                    )}
                    {(req.status === "REJECTED" || req.status === "COMPLETED") && (
                      <span className="text-gray-500 text-xs">✔ Done</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
